  'auth.choosePasswordBlurb': { en: 'Welcome, {name}. The password you were given is temporary. Choose a new one that only you know.', rw: 'Murakaza neza, {name}. Ijambobanga wahawe ni iry’agateganyo. Hitamo irindi rishya uzi wenyine.', fr: 'Bienvenue, {name}. Le mot de passe qui vous a été donné est temporaire. Choisissez-en un nouveau que vous seul connaissez.', sw: 'Karibu, {name}. Nenosiri ulilopewa ni la muda. Chagua jipya ambalo unalijua wewe peke yako.' },
  'auth.currentPassword': { en: 'Current password', rw: 'Ijambobanga ukoresha ubu', fr: 'Mot de passe actuel', sw: 'Nenosiri la sasa' },
  'auth.savePassword': { en: 'Save my password', rw: 'Bika ijambobanga ryanjye', fr: 'Enregistrer mon mot de passe', sw: 'Hifadhi nenosiri langu' },
  'auth.choosePasswordFirst': { en: 'Choose your own password to continue.', rw: 'Hitamo ijambobanga ryawe kugira ngo ukomeze.', fr: 'Choisissez votre propre mot de passe pour continuer.', sw: 'Chagua nenosiri lako ili kuendelea.' },
  'auth.currentPasswordWrong': { en: 'Your current password is not correct.', rw: 'Ijambobanga ukoresha ubu si ryo.', fr: 'Votre mot de passe actuel est incorrect.', sw: 'Nenosiri lako la sasa si sahihi.' },
  'auth.passwordSame': { en: 'Choose a password different from the current one.', rw: 'Hitamo ijambobanga ritandukanye n’iryo ukoresha ubu.', fr: 'Choisissez un mot de passe différent de l’actuel.', sw: 'Chagua nenosiri tofauti na la sasa.' },
  'account.changeMyPassword': { en: 'Change my password', rw: 'Hindura ijambobanga ryanjye', fr: 'Changer mon mot de passe', sw: 'Badilisha nenosiri langu' },
  'msg.ownPasswordChanged': { en: 'Your password has been changed.', rw: 'Ijambobanga ryawe ryahinduwe.', fr: 'Votre mot de passe a été modifié.', sw: 'Nenosiri lako limebadilishwa.' },
  'form.temporaryPasswordHint': { en: 'This password is temporary. They will choose their own the first time they sign in.', rw: 'Iri jambobanga ni iry’agateganyo. Azihitiramo irye bwite ubwa mbere yinjiye.', fr: 'Ce mot de passe est temporaire. La personne choisira le sien à sa première connexion.', sw: 'Nenosiri hili ni la muda. Atachagua lake mwenyewe mara ya kwanza atakapoingia.' },
  'user.access': { en: 'Access', rw: 'Uburenganzira', fr: 'Accès', sw: 'Ufikiaji' },
  'user.active': { en: 'Active', rw: 'Irakora', fr: 'Actif', sw: 'Hai' },
  'user.suspended': { en: 'Suspended', rw: 'Yahagaritswe', fr: 'Suspendu', sw: 'Imesimamishwa' },
  'user.passwordTemporary': { en: 'Temporary — not chosen yet', rw: 'Iry’agateganyo — ntirirahindurwa', fr: 'Temporaire — pas encore choisi', sw: 'La muda — bado halijachaguliwa' },
  'action.suspend': { en: 'Suspend', rw: 'Hagarika', fr: 'Suspendre', sw: 'Simamisha' },
  'action.reactivate': { en: 'Reactivate', rw: 'Ongera ufungure', fr: 'Réactiver', sw: 'Rejesha' },
  'msg.suspendTitle': { en: 'Suspend {name}?', rw: 'Guhagarika {name}?', fr: 'Suspendre {name} ?', sw: 'Simamisha {name}?' },
  'msg.suspendBody': { en: 'They are signed out at once and cannot sign in until you reactivate the account. Nothing they recorded is deleted.', rw: 'Ahita asohorwa kandi ntashobora kongera kwinjira kugeza wongeye gufungura konti. Nta na kimwe yanditse gisibwa.', fr: 'La personne est déconnectée immédiatement et ne pourra plus se connecter tant que vous n’aurez pas réactivé le compte. Rien de ce qu’elle a enregistré n’est supprimé.', sw: 'Anatolewa mara moja na hawezi kuingia hadi utakapoirejesha akaunti. Hakuna alichorekodi kinachofutwa.' },
  'msg.reactivateTitle': { en: 'Reactivate {name}?', rw: 'Kongera gufungura konti ya {name}?', fr: 'Réactiver {name} ?', sw: 'Rejesha {name}?' },
  'msg.reactivateBody': { en: 'They will be able to sign in again.', rw: 'Azashobora kongera kwinjira.', fr: 'La personne pourra se reconnecter.', sw: 'Ataweza kuingia tena.' },
  'msg.suspended': { en: '{name} is suspended and signed out.', rw: '{name} yahagaritswe kandi yasohowe.', fr: '{name} est suspendu et déconnecté.', sw: '{name} amesimamishwa na ametolewa.' },
  'msg.suspendedHeldWork': { en: '{name} is suspended. They still hold {approvals} approvals, {activities} activities and {plans} monthly plans — give these to someone else.', rw: '{name} yahagaritswe. Aracyafite ibyemezo {approvals}, ibikorwa {activities} n’igenamigambi rya buri kwezi {plans} — bihe undi muntu.', fr: '{name} est suspendu. Il reste {approvals} approbations, {activities} activités et {plans} plans mensuels à son nom — confiez-les à quelqu’un d’autre.', sw: '{name} amesimamishwa. Bado ana idhini {approvals}, shughuli {activities} na mipango ya mwezi {plans} — mpe mtu mwingine.' },
  'msg.reactivated': { en: '{name} can sign in again.', rw: '{name} ashobora kongera kwinjira.', fr: '{name} peut de nouveau se connecter.', sw: '{name} anaweza kuingia tena.' },
  'action.back': { en: 'Back', rw: 'Subira inyuma', fr: 'Retour', sw: 'Rudi' },
  'action.showFilters': { en: 'Show filters', rw: 'Erekana muyunguruzi', fr: 'Afficher les filtres', sw: 'Onyesha vichujio' },
  'action.hideFilters': { en: 'Hide filters', rw: 'Hisha muyunguruzi', fr: 'Masquer les filtres', sw: 'Ficha vichujio' },
