  'dialog.required': { en: 'Please fill this in.', rw: 'Nyamuneka uzuza aha.', fr: 'Veuillez remplir ce champ.', sw: 'Tafadhali jaza hapa.' },
  'dialog.newPassword': { en: 'New password', rw: 'Ijambobanga rishya', fr: 'Nouveau mot de passe', sw: 'Nenosiri jipya' },
  'dialog.repeatPassword': { en: 'Repeat the new password', rw: 'Subiramo ijambobanga rishya', fr: 'Répétez le nouveau mot de passe', sw: 'Rudia nenosiri jipya' },
  'dialog.passwordTooShort': { en: 'The password must be at least 8 characters.', rw: 'Ijambobanga rigomba kugira nibura inyuguti 8.', fr: 'Le mot de passe doit contenir au moins 8 caractères.', sw: 'Nenosiri lazima liwe na angalau herufi 8.' },
  'dialog.passwordMismatch': { en: 'The two passwords do not match.', rw: 'Amagambobanga yombi ntabwo ahura.', fr: 'Les deux mots de passe ne correspondent pas.', sw: 'Manenosiri mawili hayalingani.' },
