  'user.thisIsYou': { en: 'Your account', rw: 'Konti yawe', fr: 'Votre compte', sw: 'Akaunti yako' },
  'approval.awaitingDirector': { en: 'Awaiting the Director', rw: 'Bitegereje Umuyobozi', fr: 'En attente du Directeur', sw: 'Inasubiri Mkurugenzi' },
  'approval.recorded': { en: 'Recorded', rw: 'Byanditswe', fr: 'Enregistré', sw: 'Imerekodiwa' },
  'monthly.planSettings': { en: 'Manager and notes', rw: 'Umuyobozi n’ibisobanuro', fr: 'Responsable et notes', sw: 'Meneja na maelezo' },
  'monthly.managerChangeHint': { en: 'The month’s unfinished activities move to the new manager with it.', rw: 'Ibikorwa by’ukwezi bitarangiye bihabwa umuyobozi mushya.', fr: 'Les activités non terminées du mois passent au nouveau responsable.', sw: 'Shughuli za mwezi ambazo hazijakamilika zinahamishiwa kwa meneja mpya.' },
  'movement.createdByOn': { en: 'created by {name} on {date}', rw: 'byakozwe na {name} ku wa {date}', fr: 'créé par {name} le {date}', sw: 'imeundwa na {name} tarehe {date}' },
  'movement.fileCount': { en: '{count} file(s)', rw: 'amadosiye {count}', fr: '{count} fichier(s)', sw: 'faili {count}' },
  'report.assignedHint': { en: 'What was originally set or asked for', rw: 'Ibyari byagenwe cyangwa byasabwe mbere', fr: 'Ce qui avait été fixé ou demandé au départ', sw: 'Kilichowekwa au kuombwa awali' },
  'report.unchangedOnReview': { en: 'Unchanged on review', rw: 'Ntibyahindutse mu isuzuma', fr: 'Inchangé après examen', sw: 'Haikubadilika katika mapitio' },
  'report.againstOriginal': { en: '{change} against the original', rw: '{change} ugereranyije n’iy’ibanze', fr: '{change} par rapport à l’initial', sw: '{change} ikilinganishwa na ya awali' },
  'report.utilisationHint': { en: '{percent}% of the revised budget, from recorded expenses', rw: '{percent}% by’ingengo y’imari yavuguruwe, bivuye ku mafaranga yanditswe yakoreshejwe', fr: '{percent} % du budget révisé, d’après les dépenses enregistrées', sw: '{percent}% ya bajeti iliyorekebishwa, kutoka matumizi yaliyorekodiwa' },
  'report.overspent': { en: 'Spending has passed the released budget', rw: 'Amafaranga yakoreshejwe arenze ingengo y’imari yatanzwe', fr: 'Les dépenses ont dépassé le budget accordé', sw: 'Matumizi yamezidi bajeti iliyotolewa' },
  'report.releasedNotSpent': { en: 'Released but not yet spent', rw: 'Byatanzwe ariko ntibirakoreshwa', fr: 'Accordé mais pas encore dépensé', sw: 'Imetolewa lakini bado haijatumika' },
  'report.unassignedWork': { en: 'Work nobody has been given yet', rw: 'Akazi ntawe urahabwa', fr: 'Travail encore attribué à personne', sw: 'Kazi ambayo bado haijapewa mtu' },
