  'msg.partnerOperationTitle': { en: 'Change what this partner can see?', rw: 'Guhindura ibyo uyu mufatanyabikorwa abona?', fr: 'Modifier ce que ce partenaire peut voir ?', sw: 'Badilisha kile mshirika huyu anaweza kuona?' },
  'msg.partnerOperationBody': { en: '{name} will see {operation} only, from their next request.', rw: '{name} azabona {operation} gusa, guhera ku gikorwa gikurikira.', fr: '{name} ne verra que {operation}, dès sa prochaine requête.', sw: '{name} ataona {operation} pekee, kuanzia ombi lake lijalo.' },
  'msg.suspendTitle': { en: 'Suspend access?', rw: 'Guhagarika uburenganzira by’agateganyo?', fr: 'Suspendre l’accès ?', sw: 'Simamisha ufikiaji?' },
